      "purpose": "Check FATF Recommendation 16 originator and beneficiary data completeness for a transfer above the regime's threshold (comparison selects at_or_above or above); below it a missing name or account is reported as info.",
      "tier": "READ",
      "timeout_s": 5
    },
    {
      "name": "custody_tx_policy_eval",
      "purpose": "Evaluate a transaction descriptor against custody policy and return allow, hold or deny with reasons; it never signs.",
      "tier": "READ",
      "timeout_s": 5
    },
    {
      "name": "custody_wallet_tier_caps",
      "purpose": "Check hot, warm and cold wallet balances against percentage and absolute caps and a minimum cold share; report what to sweep.",
      "tier": "READ",
      "timeout_s": 5
    },
    {
      "name": "shared_artifact_check",
      "purpose": "Check each output of a task: local file exists, digest matches, producer is the task's agent; non-file uris are reported unchecked, never assumed fine.",
      "tier": "READ",
      "timeout_s": 120
    },
    {
      "name": "shared_artifact_digest",
      "purpose": "Compute the sha256 digest of a file inside the workspace so an artifact can be listed in a handover with a verifiable digest.",
      "tier": "READ",
      "timeout_s": 120
    },
    {
      "name": "shared_attempt_history",
      "purpose": "Show a task's attempt count, rework loops against the cap, state transitions and the last error, so a retry starts from what already failed.",
      "tier": "READ",
      "timeout_s": 15
    },
    {
      "name": "shared_cancel_check",
      "purpose": "Report whether a cooperative cancel was requested for the task's correlation, the grace left, and the seconds to its running deadline.",
      "tier": "READ",
      "timeout_s": 30
    },
    {
      "name": "shared_dod_check",
      "purpose": "Check each acceptance criterion against a supplied result by deterministic keyword and evidence matching: met only with supporting evidence, otherwise unknown.",
      "tier": "READ",
      "timeout_s": 10
    },
    {
      "name": "shared_escalate",
      "purpose": "Record escalation.request for the caller's own task and return a ready BLOCKED task.result patch plus the escalation owner.",
      "tier": "WRITE",
      "timeout_s": 30
    },
    {
      "name": "shared_escalation_owner",
      "purpose": "Name who becomes accountable when the swarm gives up on a task: A14 when a direct upstream task is A14's work order, else A01.",
      "tier": "READ",
      "timeout_s": 30
    },
    {
      "name": "shared_handover_bundle",
      "purpose": "Everything a receiver needs for one task in one bounded object: goal, acceptance criteria, handover, upstream results and needs, artifacts, signed verdict summaries (stale: true for verdicts issued before the last rework), redacted lease mirror and attempts.",
      "tier": "READ",
      "timeout_s": 30
    },
    {
      "name": "shared_handover_read",
      "purpose": "Read the newest (or a given seq) handover of a task, re-validated and digest-checked, with its status ok, missing, partial, stale or malformed and the reasons.",
      "tier": "READ",
      "timeout_s": 15
    },
    {
      "name": "shared_handover_receipt",
      "purpose": "Record, idempotently by task, receiver and digest, what the receiving agent ascertained from a handover and the questions it still has; only the addressed receiver may write it.",
      "tier": "WRITE",
      "timeout_s": 20
    },
    {
      "name": "shared_handover_validate",
      "purpose": "Validate a handover document against swarm.handover.v1 and the semantic rules before writing it; reports every problem by field, its stored size and whether it would be summarized.",
      "tier": "READ",
      "timeout_s": 10
    },
    {
      "name": "shared_handover_verify",
      "purpose": "Judge whether a task can start from its handover: handover status plus the state of every upstream task.",
      "tier": "READ",
      "timeout_s": 20
    },
    {
      "name": "shared_handover_write",
      "purpose": "Write the versioned handover for a task to the next agent: goal, done, remaining, constraints, artifacts with digests; validated, redacted, size-capped and digest-sealed, from_agent is always the caller.",
      "tier": "WRITE",
      "timeout_s": 30
    },
    {
      "name": "shared_lease_state",
      "purpose": "Show the lease mirror recorded on a task (state, holder, ttl, age, expired) with the lease id always redacted.",
      "tier": "READ",
      "timeout_s": 15
    },
    {
      "name": "shared_log_emit",
      "purpose": "Write one structured agent.log event (level, message, scalar fields) to the run log with correlation and task ids; secrets are redacted.",
      "tier": "WRITE",
      "timeout_s": 30
    },
    {
      "name": "shared_open_findings",
      "purpose": "List the unexpired findings of failing gate verdicts for a task with their gate and issuing agent, most severe first. After a rework the failing verdicts that caused it are included and flagged stale: true; a newer verdict of the same gate replaces them.",
      "tier": "READ",
      "timeout_s": 15
    },
    {
      "name": "shared_open_questions",
      "purpose": "List unresolved questions for a task: the needs of upstream results still waiting and the open questions of its handover.",
      "tier": "READ",
      "timeout_s": 15
    },
    {
      "name": "shared_route_check",
      "purpose": "Say whether ACP allows a message type from one agent to another, from the live agents.json routing matrix, and why not.",
      "tier": "READ",
      "timeout_s": 30
    },
    {
      "name": "shared_scratchpad_get",
      "purpose": "Read one scratchpad key, or list every key with its owner, version, size and update time.",
      "tier": "READ",
      "timeout_s": 30
    },
    {
      "name": "shared_scratchpad_put",
      "purpose": "Store a JSON object under a key in the per-correlation scratchpad (8 KiB value, 64 keys, owner-only overwrite unless shared, optional if_version compare-and-swap).",
      "tier": "WRITE",
      "timeout_s": 30
    },
    {
      "name": "shared_status_report",
      "purpose": "Record the caller's progress, blocked or done status for its own task and emit swarm.run.activity for the live bar.",
      "tier": "WRITE",
      "timeout_s": 30
    }
  ],
